{
  "code": "import pytest
import impl


# Basic decisions
def test_basic_allow():
    """Single matching ALLOW policy returns ALLOW."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_basic_deny():
    """Single matching DENY policy returns DENY."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies = [{"effect": "DENY", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_default_deny_empty_policies():
    """No policies defaults to DENY."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    assert impl.authorize(request, []) == "DENY"


def test_default_deny_no_matching():
    """No matching policies defaults to DENY."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies = [{"effect": "ALLOW", "principal": "user:bob", "action": "s3:GetObject", "resource": "bucket/file"}]
    assert impl.authorize(request, policies) == "DENY"


# Deny-overrides logic
def test_deny_overrides_allow_regardless_of_order():
    """Deny-overrides: any matching DENY defeats any matching ALLOW, regardless of order."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies = [
        {"effect": "DENY", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"},
        {"effect": "ALLOW", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"},
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_role_deny_beats_user_allow():
    """Role-based DENY beats user-based ALLOW (no most-specific-wins)."""
    request = {"subject": "alice", "roles": ["contractor"], "action": "docs:Read", "resource": "docs/reports/Q1"}
    policies = [
        {"effect": "DENY", "principal": "role:contractor", "action": "docs:Read", "resource": "docs/reports/*"},
        {"effect": "ALLOW", "principal": "user:alice", "action": "docs:Read", "resource": "docs/reports/*"},
    ]
    assert impl.authorize(request, policies) == "DENY"


# Principal matching
def test_principal_wildcard():
    """Principal '*' matches any request."""
    request = {"subject": "alice", "roles": ["user"], "action": "s3:GetObject", "resource": "bucket/file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:GetObject", "resource": "bucket/file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_user_exact():
    """Principal 'user:X' matches when subject is X."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_role_exact():
    """Principal 'role:X' matches when X is in request roles."""
    request = {"subject": "alice", "roles": ["admin", "user"], "action": "s3:DeleteObject", "resource": "bucket/file"}
    policies = [{"effect": "ALLOW", "principal": "role:admin", "action": "s3:DeleteObject", "resource": "bucket/file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_pattern_not_glob():
    """Principal 'user:al*' is literal string, not a glob pattern."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies = [{"effect": "ALLOW", "principal": "user:al*", "action": "s3:GetObject", "resource": "bucket/file"}]
    assert impl.authorize(request, policies) == "DENY"


# Pattern matching
def test_action_prefix_wildcard():
    """Action 's3:Get*' matches 's3:GetObject' and 's3:Get'."""
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:Get*", "resource": "bucket/file"}]

    request1 = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    assert impl.authorize(request1, policies) == "ALLOW"

    request2 = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "bucket/file"}
    assert impl.authorize(request2, policies) == "ALLOW"


def test_resource_prefix_wildcard():
    """Resource 'docs/reports/*' matches 'docs/reports/Q1.txt'."""
    request = {"subject": "alice", "roles": [], "action": "docs:Read", "resource": "docs/reports/Q1.txt"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "docs:Read", "resource": "docs/reports/*"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_resource_prefix_no_match_beyond_prefix():
    """Resource 'docs/reports/*' does not match 'docs/reportsQ1'."""
    request = {"subject": "alice", "roles": [], "action": "docs:Read", "resource": "docs/reportsQ1"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "docs:Read", "resource": "docs/reports/*"}]
    assert impl.authorize(request, policies) == "DENY"


def test_literal_asterisk_not_wildcard():
    """Non-final '*' like 's3:*Object' is literal, requires exact match."""
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:*Object", "resource": "bucket/file"}]

    # Exact match works
    request1 = {"subject": "alice", "roles": [], "action": "s3:*Object", "resource": "bucket/file"}
    assert impl.authorize(request1, policies) == "ALLOW"

    # But s3:GetObject doesn't match
    request2 = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    assert impl.authorize(request2, policies) == "DENY"


def test_case_sensitivity():
    """Matching is case-sensitive in principals and effects."""
    # Principal case sensitivity
    request1 = {"subject": "Alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies1 = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"}]
    assert impl.authorize(request1, policies1) == "DENY"

    # Effect case sensitivity
    request2 = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    policies2 = [{"effect": "Allow", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"}]
    with pytest.raises(ValueError, match="invalid effect.*Allow"):
        impl.authorize(request2, policies2)


def test_empty_and_multiple_roles():
    """Request handles empty and multiple roles correctly."""
    policies = [{"effect": "ALLOW", "principal": "role:admin", "action": "s3:GetObject", "resource": "bucket/file"}]

    # Empty roles, role pattern doesn't match
    request1 = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    assert impl.authorize(request1, policies) == "DENY"

    # Multiple roles, one matches
    request2 = {"subject": "alice", "roles": ["admin", "user"], "action": "s3:GetObject", "resource": "bucket/file"}
    assert impl.authorize(request2, policies) == "ALLOW"


# Validation
def test_request_validation_missing_fields():
    """Request validation checks all required fields."""
    for missing_field in ["subject", "roles", "action", "resource"]:
        request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
        del request[missing_field]
        with pytest.raises(ValueError, match=missing_field):
            impl.authorize(request, [])


def test_request_validation_roles_not_list():
    """Request 'roles' must be a list."""
    request = {"subject": "alice", "roles": "admin", "action": "s3:GetObject", "resource": "bucket/file"}
    with pytest.raises(ValueError, match="must be a list"):
        impl.authorize(request, [])


def test_policy_validation_missing_fields():
    """Policy validation checks all required fields before deciding."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    for missing_field in ["effect", "principal", "action", "resource"]:
        policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"}]
        del policies[0][missing_field]
        with pytest.raises(ValueError, match=missing_field):
            impl.authorize(request, policies)


def test_policy_validation_invalid_effect():
    """Policy effect must be exactly 'ALLOW' or 'DENY', with offending value in error."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket/file"}
    for bad_effect in ["Allow", "PERMIT", "Deny", "allow"]:
        policies = [{"effect": bad_effect, "principal": "user:alice", "action": "s3:GetObject", "resource": "bucket/file"}]
        with pytest.raises(ValueError, match=bad_effect):
            impl.authorize(request, policies)
